94		Observations []Observation `json:"observations"`
95	}
96	
97	type poseChangeJSON struct {
98		Before Pose `json:"before"`
99		After  Pose `json:"after"`
100	}
101	
102	type landmarkChangeJSON struct {
103		ID         string   `json:"id"`
104		Occurrence int      `json:"occurrence"` // 受影响的出现编号（1 起）；旧校正记录缺省为 1
105		Before     Landmark `json:"before"`
106		After      Landmark `json:"after"`
107	}
